public class EclExecService extends HttpServlet {
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
            Request request = RequestCustomizer.jettyRequest(req); // answer to the OP
            while (longProcessRunning) {
                ((IdleTimeout) request.getConnectionMetaData().getConnection().getEndPoint()).notIdle();
            }
        }
</code></pre>
<p>See <a href="https://stackoverflow.com/a/49393145/125562">Change Jetty configuration from code to XML</a> for an example of XML configuration.</p>
